  `description` text COLLATE utf8mb4_unicode_ci,
  `price` decimal(12,2) NOT NULL,
  `stock` int NOT NULL DEFAULT '0',
  `category_id` bigint DEFAULT NULL,
  `brand` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `images` json DEFAULT NULL COMMENT 'Array of image URLs',
  `specifications` json DEFAULT NULL COMMENT 'Product specs as JSON',
  `rating` decimal(3,2) DEFAULT '0.00',
  `review_count` int DEFAULT '0',
  `trust_score` int DEFAULT NULL COMMENT 'AI-generated 0-100',
  `trust_level` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Low/Medium/High/Excellent',
  `ai_summary` text COLLATE utf8mb4_unicode_ci COMMENT 'AI-generated review summary',
  `ai_summary_time` datetime DEFAULT NULL COMMENT 'When summary was last generated',
  `fake_review_count` int DEFAULT '0',
  `status` tinyint DEFAULT '1' COMMENT '0=inactive, 1=active',
  `seller_id` bigint DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `external_url` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'External/Taobao product URL',
  `variants` json DEFAULT NULL COMMENT 'SKU options as JSON',
  PRIMARY KEY (`id`),
  KEY `seller_id` (`seller_id`),
  KEY `idx_category` (`category_id`),
  KEY `idx_name` (`name`),
  KEY `idx_price` (`price`),
  KEY `idx_trust_score` (`trust_score`),
  CONSTRAINT `product_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `category` (`id`) ON DELETE SET NULL,
  CONSTRAINT `product_ibfk_2` FOREIGN KEY (`seller_id`) REFERENCES `user` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=190505 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
