DROP TABLE IF EXISTS `review`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `review` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `product_id` bigint NOT NULL,
  `order_id` bigint DEFAULT NULL,
  `rating` tinyint NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci,
  `images` json DEFAULT NULL COMMENT 'Array of image URLs',
  `sentiment` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'POSITIVE/NEUTRAL/NEGATIVE — AI',
  `emotion` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AI emotion detection',
  `fake_probability` decimal(5,2) DEFAULT NULL COMMENT 'AI fake review probability 0-100',
  `fake_reason` text COLLATE utf8mb4_unicode_ci COMMENT 'Why AI flagged as suspicious',
  `is_flagged` tinyint DEFAULT '0',
  `status` tinyint DEFAULT '1' COMMENT '0=hidden, 1=visible',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_product` (`product_id`),
  KEY `idx_user` (`user_id`),
  CONSTRAINT `review_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `review_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`) ON DELETE CASCADE,
  CONSTRAINT `review_chk_1` CHECK (((`rating` >= 1) and (`rating` <= 5)))
) ENGINE=InnoDB AUTO_INCREMENT=11256 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
