INSERT INTO `review` VALUES (9001,2,1,NULL,5,'Upgraded from the iPhone 12 and the difference is night and day. The camera is incredible in low light and the titanium design feels premium without being slippery. Battery easily lasts a full day of heavy use. Delivery was fast and packaging was secure.',NULL,'NEUTRAL','neutral',2.00,'Natural language patterns; Specific product details present',0,1,'2026-07-02 10:15:00','2026-08-31 15:09:57'),(9002,3,1,2,4,'Great phone overall. The A17 Pro chip handles everything I throw at it. Screen display is bright and colours are accurate. Only complaint is the price, it is expensive for what you get. Performance is snappy though.',NULL,'POSITIVE','happy',2.00,'Natural language patterns; Specific product details present',0,1,'2026-07-03 14:22:00','2026-08-31 15:09:57'),(9003,23,1,NULL,5,'Absolutely love this phone. The build quality is excellent and it feels solid in the hand. Battery life is much better than my old phone. Fast delivery too, arrived in two days.',NULL,'POSITIVE','happy',2.00,'Natural language patterns; Specific product details present',0,1,'2026-07-04 09:05:00','2026-08-31 15:09:57'),(9004,2,1,NULL,2,'Disappointed with the battery life. After a few months it degrades noticeably and I need to charge twice a day. For this price I expected better. The camera is good but the battery issue is a dealbreaker.',NULL,'NEGATIVE','disappointed',2.00,'Natural language patterns; Specific product details present',0,1,'2026-07-05 18:40:00','2026-08-31 15:09:57'),(9005,23,1,NULL,3,'Mixed feelings. The design is beautiful and the performance is fast, but it gets quite hot during gaming sessions. Price is also very high. Packaging was nice.',NULL,'NEUTRAL','neutral',10.00,'Natural language patterns; Balanced tone',0,1,'2026-07-06 11:30:00','2026-08-31 15:09:57'),(9006,3,1,NULL,5,'Best product ever!!! Amazing quality great price super fast delivery highly recommended buy now!!!',NULL,'POSITIVE','happy',97.00,'Excessive punctuation (6 exclamation marks); Promotional phrasing detected (\"buy now\"); Keyword stuffing — 5 generic praise terms in a short review; Generic praise with no verifiable product specifics; Superlative overload',1,1,'2026-07-06 12:00:00','2026-08-31 15:09:57'),(9007,23,1,NULL,5,'This is the best phone I have ever used. Perfect. Great quality. Fast shipping. Five stars!',NULL,'POSITIVE','happy',85.00,'Keyword stuffing — 4 generic praise terms in a short review; Generic praise with no verifiable product specifics; Superlative overload',1,1,'2026-07-06 12:05:00','2026-08-31 15:09:57'),(9008,2,1,NULL,5,'Excellent product great service would buy again amazing value for money top quality highly recommend',NULL,'POSITIVE','happy',70.00,'Keyword stuffing — 5 generic praise terms in a short review; Generic praise with no verifiable product specifics',1,1,'2026-07-06 12:10:00','2026-08-31 15:09:57'),(9009,3,1,3,4,'Solid upgrade. Camera photos are sharp with great dynamic range. Comfort in hand is good despite the larger size. Battery could be better but acceptable for my usage.',NULL,'POSITIVE','happy',2.00,'Natural language patterns; Specific product details present',0,1,'2026-07-08 16:45:00','2026-08-31 15:09:57'),(9010,2,1,NULL,5,'The screen display is gorgeous, 120Hz makes everything smooth. Build quality feels premium. Delivery was quick and well packaged.',NULL,'NEUTRAL','neutral',2.00,'Natural language patterns; Specific product details present',0,1,'2026-07-09 08:20:00','2026-08-31 15:09:57'),(9011,23,1,NULL,4,'Good phone, performance is excellent and the design is sleek. Slightly expensive but you get what you pay for. Battery is decent.',NULL,'POSITIVE','happy',2.00,'Natural language patterns; Specific product details present',0,1,'2026-07-10 19:10:00','2026-08-31 15:09:57'),(9012,3,1,NULL,5,'Fantastic device. The camera quality is outstanding, especially portrait mode. Screen is bright and vivid. Comfortable to hold. Highly recommend despite the price.',NULL,'NEUTRAL','neutr